(function(E){ const x = E["hr-m2"] = E["hr-m2"] || {units:{}}; x.units["hr-2-4"] = {"explain":{"id":"c-hr-2-4-e","course":"hr","unit":"hr-2-4","type":"explain","level":"B1","title":{"en":"Shortlist and report","tr":"Kısa liste ve rapor","fa":"فهرست منتخب و گزارش به مدیر"},"objective":{"en":"After this lesson, you can compare candidates with facts, not feelings, and recommend a shortlist by email.","tr":"Bu dersin sonunda adayları duygularla değil olgularla karşılaştırıp e-postayla bir kısa liste önerebileceksin.","fa":"بعد از این درس می‌توانی متقاضی‌ها را با واقعیت‌ها مقایسه کنی، نه احساس، و با ایمیل فهرست منتخب را پیشنهاد بدهی."},"hook":{"en":"Compare candidates with facts, not feelings. A manager who missed the interviews must decide from your email. Leyla almost wrote 'I like Deniz best'. She wrote facts and comparisons instead, and Omar could use them.","tr":"Adayları duygularla değil, olgularla karşılaştır. Mülakatlarda olmayan bir yönetici kararını senin e-postana bakarak verir. Leyla neredeyse 'En çok Deniz'i beğeniyorum' yazacaktı. Onun yerine bilgi ve karşılaştırma yazdı; Omar bunları kullanabildi.","fa":"متقاضی‌ها را با واقعیت‌ها مقایسه کن، نه با احساس. مدیری که در مصاحبه‌ها نبوده، باید از روی ایمیل تو تصمیم بگیرد. لیلا نزدیک بود بنویسد «دنیز را از همه بیشتر دوست دارم». به‌جایش واقعیت و مقایسه نوشت و عمر توانست از آن استفاده کند."},"before":{"en":"Compare two candidates in two sentences, with facts only, and say which one you recommend and why.","tr":"İki adayı yalnızca bilgilerle iki cümlede karşılaştır; hangisini önerdiğini ve nedenini söyle.","fa":"دو داوطلب را فقط با اطلاعات واقعی در دو جمله مقایسه کن و بگو کدام را پیشنهاد می‌کنی و چرا."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"5"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"4"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Facts first, feelings out","tr":"Önce olgular, duygular dışarıda","fa":"اول واقعیت‌ها، بدون احساس شخصی"},"body":{"en":"\"I like her\" tells the reader about you, not the candidate. A fair comparison gives the same fact for each person, then a reason for your choice.","tr":"\"Onu beğendim\" okuyana adayı değil, seni anlatır. Adil bir karşılaştırma her kişi için aynı bilgiyi verir, sonra seçiminin nedenini söyler.","fa":"«از او خوشم آمد» درباره‌ی خود تو حرف می‌زند، نه متقاضی. مقایسه‌ی منصفانه برای هر نفر همان واقعیت را می‌گوید و بعد دلیل انتخابت را."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Comparing candidates fairly","tr":"Adayları adil karşılaştırmak","fa":"مقایسه‌ی منصفانه‌ی متقاضی‌ها"},"steps":[{"en":"Short adjective + -er; long adjective: more + adjective. Then than.","tr":"Kısa sıfat + -er; uzun sıfat: more + sıfat. Ardından than.","fa":"صفت کوتاه -er می‌گیرد و صفت بلند با more می‌آید. بعدش than می‌آید.","ex":"faster than / more experienced than"},{"en":"Two contrasting facts: whereas or while.","tr":"İki zıt bilgi: whereas ya da while.","fa":"برای دو واقعیت متضاد، whereas یا while را به کار ببر.","ex":"Deniz has driven for six years, whereas Karim has driven for two."},{"en":"Both = the two; neither = not one, not the other.","tr":"Both = ikisi de; neither = ikisi de değil.","fa":"both یعنی هر دو؛ neither یعنی هیچ‌کدام از آن دو.","ex":"Both hold a Class C licence. Neither has cold-chain experience."},{"en":"Fact first, then the comparison.","tr":"Önce bilgi, sonra karşılaştırma.","fa":"اول واقعیت را بگو، بعد مقایسه کن.","ex":"Hana has four years; Karim has two."}],"table":{"headers":{"en":["Idea","Pattern"],"tr":["Fikir","Kalıp"],"fa":["منظور","الگو"]},"rows":[["More of something","Karim has more experience than Deniz."],["Contrast","..., whereas ... / While ..., ..."],["Both are true","Both candidates hold a licence."],["Neither is true","Neither has cold-chain experience."]]},"tip":{"en":"Turkish puts the comparison first (Karim'den daha deneyimli). Persian order is close to English (batajrobe-tar az Karim), but az is easy to translate as from. English always needs than: more experienced than Karim.","tr":"Türkçede karşılaştırma '-den daha' ile yapılır: 'Karim'den daha deneyimli'. İngilizcede sıra değişir ve than şarttır: more experienced than Karim; 'that' değil.","fa":"در فارسی می‌گوییم «باتجربه‌تر از کریم» و «از» بعد از صفت می‌آید. در انگلیسی هم بعد از صفت تفضیلی than لازم است، نه from یا that: «more experienced than Karim»."},"wrong":"Deniz is more experienced from Karim.","right":"Deniz is more experienced than Karim."},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"All three meet the essential requirements.","meaning":{"en":"A clear opening for a shortlist.","tr":"Kısa liste için net bir giriş.","fa":"شروعی روشن برای گزارش فهرست منتخب."}},{"phrase":"..., whereas ...","meaning":{"en":"Joins two contrasting facts.","tr":"Zıt iki olguyu bağlar.","fa":"دو واقعیتِ متضاد را به هم وصل می‌کند."}},{"phrase":"On balance, I recommend...","meaning":{"en":"Gives the final suggestion.","tr":"Son öneriyi verir.","fa":"پیشنهاد نهایی را می‌گوید."}},{"phrase":"experienced","meaning":{"en":"Having done something many times.","tr":"deneyimli.","fa":"باتجربه"}},{"phrase":"evidence","meaning":{"en":"Facts that show something is true.","tr":"kanıt.","fa":"شواهد؛ مدرک و دلیل"}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Write as if the candidate will read it","tr":"Aday okuyacakmış gibi yaz","fa":"طوری بنویس که انگار متقاضی هم آن را می‌خواند"},"body":{"en":"In many companies, the written shortlist may be read later by someone who was not at the interview, and in some countries it can be requested by a candidate. Write only what you would be happy for the candidate to read.","tr":"Birçok şirkette yazılı kısa listeyi mülakatta olmayan biri sonradan okuyabilir ve bazı ülkelerde aday bunu talep edebilir. Sadece adayın okumasından rahatsız olmayacağın şeyleri yaz.","fa":"در بسیاری از شرکت‌ها، فهرست منتخبی که می‌نویسی ممکن است بعدها به دست کسی برسد که در مصاحبه نبوده است، و در بعضی کشورها خود متقاضی هم حق دارد آن را درخواست کند. پس فقط چیزی بنویس که اگر متقاضی آن را بخواند، از نوشتنش پشیمان نشوی."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از احساس تا مقایسه با واقعیت"},"text":"Facts: First candidate: four years of night driving. Second candidate: one year.","item":"I really like the second candidate. She seems the best.","why":{"en":"Weak: a feeling, with no evidence. Strong: one fact, two people, one reason.","tr":"Zayıf: kanıtsız bir duygu. Güçlü: tek bilgi, iki kişi, bir neden.","fa":"نسخه‌ی اول یک احساس است، بدون مدرک. نسخه‌ی دوم یک واقعیت را برای دو نفر می‌گوید و یک دلیل می‌آورد."},"answer":"The first candidate has four years of night driving, whereas the second has one, so I recommend the first.","cut":["I really like the second candidate.","She seems the best."],"cutHint":{"en":"Tap the feelings: the reader needs facts.","tr":"Duygulara dokun: Okuyanın bilgiye ihtiyacı var.","fa":"روی احساسات بزن: خواننده به اطلاعات واقعی نیاز دارد."}},"quick":{"prompt":"Who might read your written shortlist later?","options":["Someone who was not at the interview, or even the candidate","Only you","Only the candidates you rejected"],"correct":0,"why":{"en":"Someone who was not there, or in some countries the candidate. So write only what you would be happy for the candidate to read.","tr":"Orada olmayan biri, bazı ülkelerde de aday. Bu yüzden yalnızca adayın okumasından rahatsız olmayacağın şeyleri yaz.","fa":"کسی که آن‌جا نبوده و در بعضی کشورها حتی خود داوطلب. پس فقط چیزی را بنویس که از خواندنش توسط داوطلب ناراحت نشوی."},"point":4,"hint2":{"en":"A written shortlist stays in the file. Who else could open that file one day?","tr":"Yazılı kısa liste dosyada kalır. O dosyayı bir gün başka kim açabilir?","fa":"فهرست کوتاهِ نوشته‌شده در پرونده می‌ماند. چه کس دیگری ممکن است روزی آن پرونده را باز کند؟"}},"remember":{"en":"Is there a feeling word (nice, smart, best) without a fact next to it? Replace it with a fact. Result of this lesson: you can compare candidates fairly. You also have a shortlist email.","tr":"Yanında bir bilgi olmayan bir duygu kelimesi (nice, smart, best) var mı? Onu bir bilgiyle değiştir. Bu dersin sonucu: adayları adil biçimde karşılaştırabilirsin ve elinde bir kısa liste e-postası olur.","fa":"کلمه‌ای احساسی (nice، smart، best) هست که کنارش واقعیتی نیامده باشد؟ به‌جایش یک واقعیت بنویس. حالا می‌توانی متقاضی‌ها را منصفانه مقایسه کنی. ایمیل فهرست منتخب هم آماده است."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Concession: although, despite, in spite of","tr":"Karşıtlık: although, despite, in spite of","fa":"تضاد: although، despite، in spite of"},"steps":[{"en":"Although + subject + verb.","tr":"Although + özne + fiil.","fa":"بعد از Although فاعل و فعل می‌آید.","ex":"Although Karim has less experience, he learned fastest."},{"en":"Despite / in spite of + noun or -ing.","tr":"Despite / in spite of + isim ya da -ing.","fa":"بعد از Despite یا in spite of اسم یا فعل -ing‌دار می‌آید.","ex":"Despite having less experience, ..."},{"en":"Want a clause after despite? Use despite the fact that.","tr":"despite'tan sonra cümle mi istiyorsun? despite the fact that kullan.","fa":"بعد از despite جمله‌ی کامل می‌خواهی؟ بنویس ⁨despite the fact that⁩.","ex":"Despite the fact that he has less experience, ..."}],"table":{"headers":{"en":["Word","Followed by","Example"],"tr":["Sözcük","Ardından","Örnek"],"fa":["کلمه","بعدش چه می‌آید","مثال"]},"rows":[["although","subject + verb","Although he has less experience, ..."],["despite","noun or -ing","Despite having less experience, ..."],["in spite of","noun or -ing","In spite of the short notice, ..."],["despite the fact that","subject + verb","Despite the fact that he is new, ..."]]},"body":{"en":"B2 track: your shortlist email must contain one concession with although and one with despite or in spite of.","tr":"B2 yolu: kısa liste e-postanda although ile bir, despite veya in spite of ile bir karşıtlık cümlesi olmalı.","fa":"مسیر B2: ایمیل فهرست منتخب تو باید یک جمله‌ی تضاد با although داشته باشد و یکی با despite یا in spite of."}},"source":{"en":"Informed by ICO guidance on recruitment records.","tr":"ICO’nun işe alım kayıtları rehberinden yararlanır.","fa":"با استفاده از راهنمای ICO درباره‌ی سوابق استخدام."}},"grammar":{"id":"c-hr-2-4-g","level":"B1","course":"hr","unit":"hr-2-4","title":"Comparing candidates fairly","titleTr":"Adayları adil karşılaştırmak","exp":{"en":"A shortlist email compares people with evidence, so you need comparatives and contrast words. Short adjectives take -er (faster, older); long ones take more (more experienced, more reliable): \"Karim has more experience than Deniz.\" Do not mix them (\"more faster\") and use \"than\", not \"that\". Whereas and while join two contrasting facts: \"Deniz has driven for six years, whereas Karim has driven for two.\" Use both for two things and neither for \"not one and not the other\": \"Both candidates hold a Class C licence. Neither has cold-chain experience.\" Always give the fact, then the comparison.","tr":"Kısa liste e-postası adayları kanıtla karşılaştırır, bu yüzden karşılaştırma yapıları ve zıtlık sözcükleri gerekir. Kısa sıfatlar -er alır (faster, older); uzun olanlar more alır (more experienced, more reliable): \"Karim has more experience than Deniz.\" İkisini karıştırma (\"more faster\") ve \"than\" kullan, \"that\" değil. Whereas ve while zıt iki bilgiyi bağlar: \"Deniz has driven for six years, whereas Karim has driven for two.\" İki kişi için both, ikisi için de olumsuz durumda neither kullan: \"Both candidates hold a Class C licence. Neither has cold-chain experience.\" Önce olguyu, sonra karşılaştırmayı yaz.","fa":"در ایمیل فهرست منتخب، متقاضیان را با شواهد مقایسه می‌کنی؛ پس به صفت تفضیلی و کلمه‌های تضاد نیاز داری. صفت‌های کوتاه ⁨-er⁩ می‌گیرند (⁨faster⁩، ⁨older⁩) و صفت‌های بلند با ⁨more⁩ می‌آیند (⁨more experienced⁩، ⁨more reliable⁩): «⁨Karim has more experience than Deniz.⁩» این دو را با هم مخلوط نکن (نه «⁨more faster⁩») و بعد از صفت تفضیلی ⁨than⁩ بیاور، نه ⁨that. whereas⁩ و ⁨while⁩ دو واقعیتِ متضاد را به هم وصل می‌کنند، مثل «در حالی که» در فارسی: «⁨Deniz has driven for six years, whereas Karim has driven for two.⁩» برای «هر دو» از ⁨both⁩ و برای «هیچ‌کدام» از ⁨neither⁩ استفاده کن: «⁨Both candidates hold a Class C licence. Neither has cold-chain experience.⁩» قاعده‌ی طلایی: اول واقعیت را بگو، بعد مقایسه کن."},"formsTable":{"headers":{"en":["Idea","Pattern"],"tr":["Fikir","Kalıp"],"fa":["منظور","الگو"]},"rows":[["More of something","Karim has more experience than Deniz."],["Contrast","..., whereas ... / While ..., ..."],["Both are true","Both candidates hold a licence."],["Neither is true","Neither has cold-chain experience."]]},"wrong":"Karim has more experience that Deniz.","right":"Karim has more experience than Deniz.","blank":{"sentence":"Karim has ___ experience than Deniz.","word":"more","distractors":["most","much"]},"wrong2":"Deniz has driven for six years, therefore Karim has driven for two.","right2":"Deniz has driven for six years, whereas Karim has driven for two.","blank2":{"sentence":"Deniz has driven for six years, ___ Karim has driven for two.","word":"whereas","distractors":["therefore","despite"]},"expParts":{"hook":{"en":"Leyla almost wrote 'I like Deniz best'. She wrote facts and comparisons instead, and Omar could use them.","tr":"Leyla neredeyse 'En çok Deniz'i beğeniyorum' yazacaktı. Onun yerine bilgi ve karşılaştırma yazdı; Omar bunları kullanabildi.","fa":"لیلا نزدیک بود بنویسد «دنیز را از همه بیشتر دوست دارم». به‌جایش واقعیت و مقایسه نوشت و عمر توانست از آن استفاده کند."},"tryWhy":{"en":"whereas: it joins two contrasting facts. therefore means 'so', and despite needs a noun.","tr":"whereas: iki zıt bilgiyi birleştirir. therefore 'bu yüzden' demektir, despite ise isim ister.","fa":"جواب whereas است: دو واقعیت متضاد را به هم وصل می‌کند. therefore یعنی «بنابراین» و despite اسم می‌خواهد."},"rule":[{"en":"Short adjective + -er; long adjective: more + adjective. Then than.","tr":"Kısa sıfat + -er; uzun sıfat: more + sıfat. Ardından than.","fa":"صفت کوتاه -er می‌گیرد و صفت بلند با more می‌آید. بعدش than می‌آید.","ex":"faster than / more experienced than"},{"en":"Two contrasting facts: whereas or while.","tr":"İki zıt bilgi: whereas ya da while.","fa":"برای دو واقعیت متضاد، whereas یا while را به کار ببر.","ex":"Deniz has driven for six years, whereas Karim has driven for two."},{"en":"Both = the two; neither = not one, not the other.","tr":"Both = ikisi de; neither = ikisi de değil.","fa":"both یعنی هر دو؛ neither یعنی هیچ‌کدام از آن دو.","ex":"Both hold a Class C licence. Neither has cold-chain experience."},{"en":"Fact first, then the comparison.","tr":"Önce bilgi, sonra karşılaştırma.","fa":"اول واقعیت را بگو، بعد مقایسه کن.","ex":"Hana has four years; Karim has two."}],"test":{"en":"Is there a feeling word (nice, smart, best) without a fact next to it? Replace it with a fact.","tr":"Yanında bir bilgi olmayan bir duygu kelimesi (nice, smart, best) var mı? Onu bir bilgiyle değiştir.","fa":"کلمه‌ای احساسی (nice، smart، best) هست که کنارش واقعیتی نیامده باشد؟ به‌جایش یک واقعیت بنویس."},"contrast":{"en":"Turkish puts the comparison first (Karim'den daha deneyimli). Persian order is close to English (batajrobe-tar az Karim), but az is easy to translate as from. English always needs than: more experienced than Karim.","tr":"Türkçede karşılaştırma '-den daha' ile yapılır: 'Karim'den daha deneyimli'. İngilizcede sıra değişir ve than şarttır: more experienced than Karim; 'that' değil.","fa":"در فارسی می‌گوییم «باتجربه‌تر از کریم» و «از» بعد از صفت می‌آید. در انگلیسی هم بعد از صفت تفضیلی than لازم است، نه from یا that: «more experienced than Karim»."}},"errorWatch":[{"find":["more experience that","more experienced that","more faster","more better","more fluent that","faster that","more experienced from","more experience from"],"fix":{"en":"Use than after a comparative, and do not add more to an -er word: 'faster than', 'more experienced than'.","tr":"Karşılaştırmadan sonra than kullan ve -er almış sıfata more ekleme: 'faster than', 'more experienced than'.","fa":"بعد از صفت تفضیلی ⁨than⁩ بیاور و به صفتی که ⁨-er⁩ دارد ⁨more⁩ اضافه نکن: «⁨faster than⁩» و «⁨more experienced than⁩»."}},{"find":["i like deniz best","seems smart","is nice","is very nice"],"fix":{"en":"This is a feeling, not evidence. Give a fact: years, licence, references, availability.","tr":"Bu bir duygu, kanıt değil. Bir bilgi ver: yıl, ehliyet, referans, uygunluk.","fa":"این احساس است، نه شاهد. یک واقعیت بنویس: سال‌های سابقه، گواهینامه، معرف‌ها، زمان آمادگی."}}]},"b2":{"id":"c-hr-2-4-b2","level":"B2","track":"B2","course":"hr","unit":"hr-2-4","title":"Concession: although, despite, in spite of","titleTr":"Karşıtlık: although, despite, in spite of","exp":{"en":"A fair shortlist admits a weakness and still makes a point. That is concession. Although is followed by a full clause (subject + verb): \"Although Karim has less experience, he learned our system fastest.\" Despite and in spite of are followed by a noun or an -ing form, never by a full clause: \"Despite having less experience, Karim learned our system fastest.\", \"In spite of the short notice, she attended the interview.\" So: not \"Despite he has less experience\" and not \"In spite the short notice\" (of is needed). If you want a clause after despite, use \"despite the fact that\".","tr":"Adil bir kısa liste bir zayıflığı kabul eder ve yine de bir noktayı vurgular. Buna karşıtlık (concession) denir. Although'tan sonra tam bir yan cümle (özne + fiil) gelir: \"Although Karim has less experience, he learned our system fastest.\" Despite ve in spite of'tan sonra ise isim veya -ing biçimi gelir, asla tam cümle gelmez: \"Despite having less experience, Karim learned our system fastest.\", \"In spite of the short notice, she attended the interview.\" Türkçedeki \"-mesine rağmen\" yapısına benzer. Yani \"Despite he has less experience\" değil, \"In spite the short notice\" de değil (of gerekir). Despite'tan sonra cümle istiyorsan \"despite the fact that\" kullan.","fa":"فهرست منتخب منصفانه نقطه‌ی ضعف را هم می‌گوید و باز حرف خودش را می‌زند. به این کار در دستور زبان انگلیسی ⁨concession⁩ می‌گویند. بعد از ⁨although⁩ یک جمله‌ی کامل (فاعل + فعل) می‌آید، درست مثل «با اینکه» در فارسی: «⁨Although Karim has less experience, he learned our system fastest.⁩» اما بعد از ⁨despite⁩ و ⁨in spite of⁩ فقط اسم یا شکل ⁨-ing⁩ می‌آید، هرگز جمله‌ی کامل؛ مثل «با وجودِ» در فارسی: «⁨Despite having less experience, Karim learned our system fastest.⁩» و «⁨In spite of the short notice, she attended the interview.⁩» پس «⁨Despite he has less experience⁩» غلط است، و «⁨In spite the short notice⁩» هم غلط است (⁨of⁩ لازم است). اگر بعد از ⁨despite⁩ جمله‌ی کامل می‌خواهی، بگو «⁨despite the fact that⁩»."},"formsTable":{"headers":{"en":["Word","Followed by","Example"],"tr":["Sözcük","Ardından","Örnek"],"fa":["کلمه","بعدش چه می‌آید","مثال"]},"rows":[["although","subject + verb","Although he has less experience, ..."],["despite","noun or -ing","Despite having less experience, ..."],["in spite of","noun or -ing","In spite of the short notice, ..."],["despite the fact that","subject + verb","Despite the fact that he is new, ..."]]},"wrong":"Despite he has less experience, Karim learned our system fastest.","right":"Although he has less experience, Karim learned our system fastest.","blank":{"sentence":"___ having less experience, Karim learned our system fastest.","word":"Despite","distractors":["Although","However"]},"wrong2":"In spite the short notice, she attended the interview.","right2":"In spite of the short notice, she attended the interview.","blank2":{"sentence":"In spite ___ the short notice, she attended the interview.","word":"of","distractors":["that","to"]},"useIn":{"en":"B2 track: your shortlist email must contain one concession with although and one with despite or in spite of.","tr":"B2 yolu: kısa liste e-postanda although ile bir, despite veya in spite of ile bir karşıtlık cümlesi olmalı.","fa":"مسیر B2: ایمیل فهرست منتخب تو باید یک جمله‌ی تضاد با although داشته باشد و یکی با despite یا in spite of."},"exitItem":{"from":"hr-2-4","kind":"blank","prompt":"___ the late start, Hana finished all her deliveries.","options":["Although","In spite of","However"],"correct":1,"why":{"en":"In spite of: it goes before a noun (the late start). 'Although' needs a full clause, and 'However' starts a new sentence.","tr":"In spite of: bir isimden önce gelir (the late start). 'Although' tam yan cümle ister; 'However' yeni bir cümle başlatır.","fa":"In spite of درست است، چون قبل از اسم می‌آید (the late start). although جمله‌ی کامل می‌خواهد و however جمله‌ی تازه شروع می‌کند."},"hint2":{"en":"Look right after the gap: is there a subject and a verb, or only a noun phrase (the late start)?","tr":"Boşluğun hemen sağına bak: Bir özne ve fiil mi var, yoksa yalnızca bir isim öbeği mi (the late start)?","fa":"بلافاصله بعد از جای خالی را ببین: فاعل و فعل آمده یا فقط یک گروه اسمی (⁨the late start⁩)؟"}},"expParts":{"hook":{"en":"A fair report admits a weakness and still makes its point: 'Although he has less experience, Karim learned fastest.'","tr":"Adil bir rapor zayıf noktayı kabul eder ve yine de görüşünü söyler: 'Although he has less experience, Karim learned fastest.'","fa":"گزارش منصفانه ضعف را هم می‌گوید و باز حرف خودش را می‌زند: «⁨Although he has less experience, Karim learned fastest.⁩»"},"tryWhy":{"en":"of: it is always 'in spite of'. Without of, the phrase is broken.","tr":"of: kalıp her zaman 'in spite of'tur. of olmadan yapı bozulur.","fa":"جواب of است: این عبارت همیشه in spite of است و بدون of جمله ناقص می‌شود."},"rule":[{"en":"Although + subject + verb.","tr":"Although + özne + fiil.","fa":"بعد از Although فاعل و فعل می‌آید.","ex":"Although Karim has less experience, he learned fastest."},{"en":"Despite / in spite of + noun or -ing.","tr":"Despite / in spite of + isim ya da -ing.","fa":"بعد از Despite یا in spite of اسم یا فعل -ing‌دار می‌آید.","ex":"Despite having less experience, ..."},{"en":"Want a clause after despite? Use despite the fact that.","tr":"despite'tan sonra cümle mi istiyorsun? despite the fact that kullan.","fa":"بعد از despite جمله‌ی کامل می‌خواهی؟ بنویس ⁨despite the fact that⁩.","ex":"Despite the fact that he has less experience, ..."}],"test":{"en":"Is there a subject and a verb right after the word? Then it must be although.","tr":"Kelimenin hemen ardından özne ve fiil mi geliyor? O zaman although olmalı.","fa":"بلافاصله بعد از این کلمه فاعل و فعل آمده؟ پس باید although باشد."},"contrast":{"en":"Persian ba inke works like although (+ clause) and ba vojud-e like despite (+ noun). Turkish -mesine rağmen covers both, so learners mix them.","tr":"Türkçede '-mesine rağmen' ve 'rağmen' her iki yapıyı da karşılar; bu yüzden although ile despite karışır. Kural: although'dan sonra cümle, despite'tan sonra isim ya da -ing.","fa":"«با اینکه» در فارسی مثل although است و بعدش جمله‌ی کامل می‌آید؛ «با وجودِ» مثل despite است و بعدش اسم می‌آید. همین مقایسه را به خاطر بسپار."}},"errorWatch":[{"find":["despite he","despite she","despite they","despite it is","despite of"],"fix":{"en":"Despite takes a noun or -ing: 'Despite having less experience, ...' or use 'Although he has...'.","tr":"Despite isim ya da -ing alır: 'Despite having less experience, ...' ya da 'Although he has...' kullan.","fa":"بعد از ⁨despite⁩ اسم یا ⁨-ing⁩ می‌آید: «⁨Despite having less experience, ...⁩» یا بنویس «⁨Although he has...⁩»."}},{"find":["in spite the","in spite he","in spite she"],"fix":{"en":"Use 'in spite of' + noun: 'In spite of the short notice, ...'","tr":"'in spite of' + isim kullan: 'In spite of the short notice, ...'","fa":"بنویس «in spite of» و بعد اسم: «In spite of the short notice, ...»"}}]},"vocab":{"id":"c-hr-2-4-v","level":"B1","category":"vocab","course":"hr","unit":"hr-2-4","goals":["career"],"title":{"en":"Comparing Candidates","tr":"Adayları Karşılaştırmak","fa":"مقایسه‌ی متقاضیان"},"cards":[{"word":"shortlist","sentence":"I have shortlisted three candidates.","gap":"shortlisted","accept":["shortlisted","shortlist"],"meaning":{"en":"To choose the best few from many applicants.","tr":"kısa listeye almak.","fa":"به فهرست منتخب بردن؛ از میان متقاضیان چند نفر برتر را انتخاب کردن"}},{"word":"strength","sentence":"His main strength is calm customer service.","meaning":{"en":"Something a person does well.","tr":"güçlü yön.","fa":"نقطه‌ی قوت"}},{"word":"weakness","sentence":"Her only weakness is limited night-shift experience.","meaning":{"en":"Something a person finds difficult.","tr":"zayıf yön.","fa":"نقطه‌ی ضعف"}},{"word":"experienced","sentence":"He is more experienced than the others.","meaning":{"en":"Having done something many times.","tr":"deneyimli.","fa":"باتجربه"}},{"word":"reliable","sentence":"Her references say she is very reliable.","meaning":{"en":"Someone you can trust to do what they say.","tr":"güvenilir.","fa":"قابل اعتماد؛ کسی که سر حرفش می‌ماند"}},{"word":"reference","sentence":"I have called both references.","gap":"references","accept":["references","reference"],"meaning":{"en":"A person who describes your work, or their statement.","tr":"referans.","fa":"معرف؛ توصیه‌نامه (کسی که درباره‌ی سابقه‌ی کاری تو نظر می‌دهد، یا خودِ نظر او)"}},{"word":"meet the requirements","sentence":"All three meet the essential requirements.","gap":"meet the essential requirements","accept":["meet the essential requirements","meet the requirements"],"meaning":{"en":"To have everything that is needed.","tr":"gereksinimleri karşılamak.","fa":"همه‌ی شرایط لازم را داشتن"}},{"word":"recommend","sentence":"I recommend inviting Deniz and Hana.","meaning":{"en":"To suggest that something is a good idea.","tr":"önermek.","fa":"توصیه کردن؛ پیشنهاد کردن"}},{"word":"on balance","sentence":"On balance, Karim is the stronger choice.","meaning":{"en":"After thinking about all the points.","tr":"her şey düşünüldüğünde.","fa":"با در نظر گرفتن همه‌ی جوانب؛ در مجموع"}},{"word":"evidence","sentence":"Each point needs evidence from the CV or the call.","meaning":{"en":"Facts that show something is true.","tr":"kanıt.","fa":"شواهد؛ مدرک و دلیل"}}]},"story":{"id":"c-hr-2-4-s","level":"B1","genre":"Workplace","course":"hr","unit":"hr-2-4","title":{"en":"Three Names","tr":"Üç İsim","fa":"سه اسم"},"text":"By Friday, Leyla had screened eighteen people. Three names were left on her list: Deniz Aydin, Karim Nasser and Hana Yilmaz.\n\nShe opened a table. Under Deniz she wrote: six years of driving, Class C, clear answers, one month's notice. Under Karim: two years, Class C, very good English, available immediately. Under Hana: four years, Class C, cold-chain experience, two good references.\n\nOmar had asked for a recommendation by Monday. He did not read long emails. Leyla knew he would read the first three lines and then decide.\n\nShe started writing. \"All three candidates meet the essential requirements.\" True, and short. Then the hard part: who is better? She did not want to write \"Deniz is nice\" or \"Karim seems smart\". She wanted facts.\n\n\"Deniz has more experience than Karim, whereas Karim speaks more fluent English. Hana is the only candidate with cold-chain experience, which Omar called a big plus.\"\n\nShe read it back. It was fair, and Omar could use it. But there was one thing she did not write. Karim was available immediately, and Omar was impatient. That was a real strength, and she had almost left it out because she liked Deniz more.\n\nShe added it. Then she changed her last line from \"I like Deniz best\" to: \"On balance, I recommend inviting all three, starting with Hana and Deniz.\"","vocab":[{"word":"screen","en":"To check applicants to choose the best ones.","tr":"ön elemeden geçirmek","fa":"غربال کردن؛ بررسی اولیه‌ی متقاضیان"},{"word":"table","en":"Information in rows and columns.","tr":"tablo","fa":"جدول"},{"word":"fluent","en":"Speaking easily, with few stops.","tr":"akıcı","fa":"روان (در صحبت کردن)"},{"word":"impatient","en":"Not wanting to wait.","tr":"sabırsız","fa":"بی‌حوصله؛ عجول"},{"word":"fair","en":"Honest and equal for everyone.","tr":"adil","fa":"منصفانه؛ عادلانه"}],"quiz":[{"prompt":"Why did Leyla add Karim's immediate availability?","options":["It was a real strength and she had almost left it out","Omar asked her to hide it","She liked Karim most"],"correct":0},{"prompt":"Choose the correct sentence.","options":["Deniz has more experience that Karim.","Deniz has more experience than Karim.","Deniz has most experience than Karim."],"correct":1},{"prompt":"Why did she change \"I like Deniz best\"?","options":["A personal feeling is not evidence","It was too long","It was a mistake in grammar"],"correct":0},{"prompt":"How might Hana feel if she saw the email?","options":["Pleased that her cold-chain experience was noticed","Angry at Leyla","Sure she would not be invited"],"correct":0}],"notice":{"en":"Leyla almost leaves one fact out of her email. Which one, and why?","tr":"Leyla e-postasına neredeyse bir bilgiyi koymayacaktı. Hangisi ve neden?","fa":"لیلا نزدیک بود یک واقعیت را در ایمیلش ننویسد. کدام را و چرا؟"},"bridge":{"en":"'Deniz has more experience than Karim, whereas...' Next: see how fair comparisons are built.","tr":"'Deniz has more experience than Karim, whereas...' Sırada: adil karşılaştırmaların nasıl kurulduğunu gör.","fa":"«⁨Deniz has more experience than Karim, whereas...⁩» قدم بعد: ببین مقایسه‌ی منصفانه چطور ساخته می‌شود."}},"speaking":{"id":"hr-2-4","course":"hr","unit":"hr-2-4","topic":{"en":"Presenting a Shortlist to a Manager","tr":"Bir Yöneticiye Kısa Liste Sunmak","fa":"ارائه‌ی فهرست منتخب به مدیر"},"warmup":{"en":"When you choose between two options at work, which facts do you check first?","tr":"İşte iki seçenek arasında seçim yaparken önce hangi olgulara bakarsın?","fa":"در کار، وقتی باید بین دو گزینه یکی را انتخاب کنی، اول کدام واقعیت‌ها را بررسی می‌کنی؟"},"questions":[{"en":"Tell Omar in 30 seconds which candidates meet the essential requirements.","tr":"Omar'a 30 saniyede hangi adayların zorunlu gereksinimleri karşıladığını söyle.","fa":"در ۳۰ ثانیه به عمر بگو کدام متقاضیان همه‌ی شرایط الزامی را دارند."},{"en":"Compare two candidates with one contrast: \"..., whereas ...\".","tr":"İki adayı tek bir zıtlıkla karşılaştır: \"..., whereas ...\".","fa":"دو متقاضی را با یک جمله‌ی تضاد مقایسه کن: «⁨..., whereas ...⁩»."},{"en":"Give your recommendation with a reason.","tr":"Önerini bir sebeple ver.","fa":"توصیه‌ات را همراه با دلیل بگو."}],"followups":[{"en":"Omar asks: \"But who is the best?\" Answer with a fact, not a feeling.","tr":"Omar soruyor: \"Ama en iyisi kim?\" Bir duyguyla değil, bir olguyla cevap ver.","fa":"عمر می‌پرسد: «⁨But who is the best?⁩» با یک واقعیت جواب بده، نه با یک حس."},{"en":"Now compare two people you know for one task, fairly, with facts only.","tr":"Şimdi tanıdığın iki kişiyi bir iş için, sadece gerçeklerle ve adil biçimde karşılaştır.","fa":"حالا دو نفر را که می‌شناسی برای یک کار، منصفانه و فقط با واقعیت‌ها مقایسه کن."}],"expressions":[{"phrase":"All three meet the essential requirements.","meaning":{"en":"A clear opening for a shortlist.","tr":"Kısa liste için net bir giriş.","fa":"شروعی روشن برای گزارش فهرست منتخب."}},{"phrase":"..., whereas ...","meaning":{"en":"Joins two contrasting facts.","tr":"Zıt iki olguyu bağlar.","fa":"دو واقعیتِ متضاد را به هم وصل می‌کند."}},{"phrase":"On balance, I recommend...","meaning":{"en":"Gives the final suggestion.","tr":"Son öneriyi verir.","fa":"پیشنهاد نهایی را می‌گوید."}}],"culture":{"en":"In many companies, the written shortlist may be read later by someone who was not at the interview, and in some countries it can be requested by a candidate. Write only what you would be happy for the candidate to read.","tr":"Birçok şirkette yazılı kısa listeyi mülakatta olmayan biri sonradan okuyabilir ve bazı ülkelerde aday bunu talep edebilir. Sadece adayın okumasından rahatsız olmayacağın şeyleri yaz.","fa":"در بسیاری از شرکت‌ها، فهرست منتخبی که می‌نویسی ممکن است بعدها به دست کسی برسد که در مصاحبه نبوده است، و در بعضی کشورها خود متقاضی هم حق دارد آن را درخواست کند. پس فقط چیزی بنویس که اگر متقاضی آن را بخواند، از نوشتنش پشیمان نشوی."},"model":"Omar, all three candidates meet the essential requirements. Deniz has more experience than Karim, whereas Karim speaks more fluent English and is available immediately. Hana is the only one with cold-chain experience. Both Deniz and Hana have strong references. On balance, I recommend inviting all three, starting with Hana and Deniz, because cold-chain experience was your big plus.","selfCheck":[{"en":"I started with who meets the essential requirements.","tr":"Zorunlu şartları kimin karşıladığıyla başladım.","fa":"اول گفتم چه کسی شرط‌های الزامی را دارد."},{"en":"I made at least one comparison with than and one with whereas.","tr":"En az bir karşılaştırmayı than ile, birini whereas ile yaptım.","fa":"دست‌کم یک مقایسه با than و یکی با whereas انجام دادم."},{"en":"Every judgement had a fact behind it.","tr":"Her değerlendirmemin arkasında bir bilgi vardı.","fa":"پشت هر قضاوتم یک واقعیت بود."},{"en":"I ended with 'On balance, I recommend...' and a reason.","tr":"'On balance, I recommend...' ve bir gerekçeyle bitirdim.","fa":"با «⁨On balance, I recommend...⁩» و یک دلیل تمام کردم."}]},"writing":{"id":"c-hr-2-4-w","title":{"en":"The shortlist email to Omar","tr":"Omar'a kısa liste e-postası","fa":"ایمیل فهرست منتخب به عمر"},"course":"hr","unit":"hr-2-4","type":"writing","difficulty":"medium","prompt":{"en":"Write the shortlist email to Omar (60-80 words) comparing Deniz, Karim and Hana with facts: who meets the essentials, two comparisons, and a recommendation with a reason.","tr":"Omar'a Deniz, Karim ve Hana'yı olgularla karşılaştıran kısa liste e-postası yaz (60-80 kelime): kim zorunlu şartları karşılıyor, iki karşılaştırma ve sebepli bir öneri.","fa":"ایمیل فهرست منتخب را برای عمر بنویس (۶۰ تا ۸۰ کلمه) و دنیز، کریم و هانا را با واقعیت‌ها مقایسه کن: چه کسی شرایط الزامی را دارد، دو مقایسه و یک توصیه همراه با دلیل."},"model":"Dear Omar, I have shortlisted three candidates for the driver role. All three meet the essential requirements. Deniz has more experience than Karim, whereas Karim speaks more fluent English and is available immediately. Hana is the only candidate with cold-chain experience. Both Deniz and Hana have strong references. On balance, I recommend inviting all three, starting with Hana and Deniz. Kind regards, Leyla","frame":"Dear ___, I have shortlisted ___ candidates for ___. All ___ meet ___. ___ has more ___ than ___, whereas ___. ___ is the only candidate with ___. On balance, I recommend ___. Kind regards, ___","words":[{"word":"whereas"},{"word":"more"},{"word":"on balance"}],"minWords":60,"minSentences":6,"rubric":["Task done: essentials, 2 comparisons, recommendation with reason","Organised: summary first, comparisons, recommendation","Language: more ... than; whereas; both/neither used correctly","Tone: objective, evidence not feelings"],"rubricI18n":{"tr":["Görev: zorunlu şartlar, 2 karşılaştırma, gerekçeli öneri","Düzen: önce özet, sonra karşılaştırmalar, sonra öneri","Dil: more ... than; whereas; both/neither doğru kullanılmış","Üslup: nesnel; duygu değil kanıt"],"fa":["کامل بودن کار: شرط‌های الزامی، دو مقایسه، پیشنهاد با دلیل","نظم: اول خلاصه، بعد مقایسه‌ها، بعد پیشنهاد","زبان: more ... than؛ whereas؛ کاربرد درست both/neither","لحن: عینی؛ شواهد، نه احساسات"]},"portfolio":null,"parts":[{"t":{"en":"Who meets the essentials","tr":"Zorunlu şartları kimin karşıladığı","fa":"اینکه چه کسی شرایط ضروری را دارد"},"find":["essential","meet","meets"],"sample":"all three meet the essentials"},{"t":{"en":"A first comparison with a fact","tr":"Bilgiye dayalı ilk karşılaştırma","fa":"مقایسه‌ی اول با یک واقعیت"},"find":["more","than"],"sample":"Deniz: more experience than Karim"},{"t":{"en":"A second comparison","tr":"İkinci karşılaştırma","fa":"مقایسه‌ی دوم"},"find":["whereas","only candidate","both"],"sample":"Karim: more fluent English; Hana: the only one with cold-chain"},{"t":{"en":"Your recommendation and its reason","tr":"Önerin ve gerekçesi","fa":"پیشنهادت و دلیلش"},"find":["recommend","on balance"],"sample":"invite all three, Hana and Deniz first"}]},"perspective":{"id":"c-hr-2-4-p","title":{"en":"Omar with 40 unread emails","tr":"40 okunmamış e-postayla Omar","fa":"عمر با ۴۰ ایمیل خوانده‌نشده"},"course":"hr","unit":"hr-2-4","type":"perspective","minSentences":2,"prompt":{"en":"You are Omar, the hiring manager, with 40 unread emails. Write 2 sentences in first person: what do you need to see in the first three lines of Leyla's email?","tr":"40 okunmamış e-postası olan işe alım yöneticisi Omar'sın. Birinci tekil şahısla 2 cümle yaz: Leyla'nın e-postasının ilk üç satırında ne görmek istersin?","fa":"تو عمر هستی، مدیری که برای واحدش نیرو استخدام می‌کند، و ۴۰ ایمیل خوانده‌نشده داری. از زبان خودت دو جمله بنویس: در سه خط اول ایمیل لیلا باید چه چیزی ببینی؟"}},"exit":{"id":"c-hr-2-4-x","course":"hr","unit":"hr-2-4","type":"exit","items":[{"from":"hr-2-4","kind":"blank","prompt":"Hana's route was ___ than Karim's.","options":["longest","longer","more long"],"correct":1,"point":2,"why":{"en":"longer: a short adjective takes -er to compare two things. 'Longest' compares three or more, and 'more long' is wrong for a short word.","tr":"longer: kısa sıfat iki şeyi karşılaştırmak için -er alır. 'Longest' üç ve daha fazlasını karşılaştırır; kısa kelimede 'more long' yanlıştır.","fa":"⁨longer⁩ درست است، چون صفت کوتاه برای مقایسه‌ی دو چیز ⁨-er⁩ می‌گیرد. ⁨longest⁩ برای سه یا بیشتر است و ⁨more long⁩ برای کلمه‌ی کوتاه غلط است."}},{"from":"hr-2-4","kind":"blank","prompt":"Karim speaks Arabic, ___ Hana speaks English and Turkish.","options":["whereas","therefore","despite"],"correct":0,"point":2,"why":{"en":"whereas: it sets two facts side by side as a contrast. 'Therefore' gives a result, and 'despite' needs a noun.","tr":"whereas: iki bilgiyi karşıtlık olarak yan yana koyar. 'Therefore' sonuç bildirir; 'despite' isim ister.","fa":"whereas درست است، چون دو واقعیت را در تقابل کنار هم می‌گذارد. therefore نتیجه را می‌گوید و despite اسم می‌خواهد."}},{"from":"hr-2-4","kind":"mcq","prompt":"\"Neither candidate has cold-chain experience\" means...","options":["Both lack it.","Both have it.","One has it."],"correct":0,"point":3,"why":{"en":"Both lack it: 'neither' means not one and not the other. 'Both have it' is the opposite, and 'one has it' would be 'only one'.","tr":"İkisinde de yok: 'neither' ne biri ne öbürü demektir. 'Both have it' tersidir; 'one has it' 'only one' olurdu.","fa":"هیچ‌کدام ندارند؛ neither یعنی نه این و نه آن. Both have it برعکس است و One has it یعنی فقط یکی."},"hint2":{"en":"Neither is the opposite of both: it says no about each of the two. Which option says that?","tr":"Neither, both’un tersidir: İkisinin her biri için hayır der. Hangi seçenek bunu söylüyor?","fa":"⁨neither⁩ برعکس ⁨both⁩ است: درباره‌ی هر دو نفر «نه» می‌گوید. کدام گزینه همین را می‌گوید؟"}},{"from":"hr-2-3","kind":"blank","prompt":"Could you tell me ___ your notice period is?","options":["what","what is","what do"],"correct":0,"point":2,"why":{"en":"what: inside 'Could you tell me...', use statement order: what your notice period is. 'What is' is question order, and 'what do' needs a main verb.","tr":"what: 'Could you tell me...' içinde düz sıra kullanılır: what your notice period is. 'What is' soru sırasıdır; 'what do' ana fiil ister.","fa":"what درست است، چون بعد از Could you tell me ترتیب خبری می‌آید: what your notice period is. what is ترتیب سؤالی است و what do فعل اصلی می‌خواهد."},"hint2":{"en":"After Could you tell me, the question becomes a statement and the verb goes to the end. Which option keeps the verb out of the gap?","tr":"Could you tell me’dan sonra soru düz cümleye döner ve fiil sona gider. Hangi seçenek fiili boşluğa koymuyor?","fa":"بعد از ⁨Could you tell me⁩، سؤال به جمله‌ی خبری تبدیل می‌شود و فعل به آخر می‌رود. کدام گزینه فعل را در جای خالی نمی‌آورد؟"}},{"from":"hr-2-1","kind":"blank","prompt":"Knowledge of the Sharjah routes ___ an advantage.","options":["would be","is being","would"],"correct":0,"point":2,"why":{"en":"would be: a desirable extra is softened with 'would be an advantage'. 'Is being' is wrong for a state, and 'would' alone needs a verb.","tr":"would be: istenen bir artı 'would be an advantage' ile yumuşatılır. 'Is being' durum için yanlıştır; tek başına 'would' fiil ister.","fa":"would be درست است، چون امتیاز دلخواه با would be an advantage نرم گفته می‌شود. is being برای حالت غلط است و would تنها فعل می‌خواهد."},"hint2":{"en":"This point is desirable, not essential. Which option is a complete, softer verb phrase?","tr":"Bu şart zorunlu değil, tercih sebebi. Hangi seçenek tam ve daha yumuşak bir fiil öbeği?","fa":"این شرط ضروری نیست، امتیاز است. کدام گزینه یک عبارت فعلیِ کامل و نرم‌تر است؟"}},{"from":"hr-1-1","kind":"blank","prompt":"Today Leyla ___ from home because of the storm.","options":["works","is working","work"],"correct":1,"point":2,"why":{"en":"is working: 'today' with a storm is temporary, so is + -ing. 'Works' is a routine, and 'work' doesn't agree with Leyla.","tr":"is working: fırtına yüzünden 'today' geçicidir, bu yüzden is + -ing. 'Works' bir rutindir; 'work' Leyla ile uyuşmaz.","fa":"is working درست است، چون today به خاطر طوفان موقتی است و is و فعل ing‌دار لازم است. works برنامه‌ی همیشگی است و work با Leyla جور نیست."}},{"from":"hr-2-4","kind":"mcq","prompt":"Which sentence belongs in a fair shortlist report?","options":["Hana has three years of cold-chain experience; Karim has none.","I have a good feeling about Hana.","Karim seems a bit quiet."],"correct":0,"why":{"en":"The first: it gives the same fact for each person. Feelings tell the reader about you, not the candidate.","tr":"İlki: Her kişi için aynı türden bir bilgi veriyor. Duygular okuyana adayı değil, seni anlatır.","fa":"گزینه‌ی اول: برای هر نفر همان نوع اطلاعات را می‌دهد. احساسات به خواننده درباره‌ی تو می‌گویند، نه درباره‌ی داوطلب."},"point":1}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
